// Souris — Jest manual mock of expo-crypto
//
// jest-expo replaces the native ExpoCrypto module with an autogenerated stub
// whose `randomUUID()` returns undefined. Tests that create Clients,
// Services, Appointments, Products, or Sales need genuine UUID v4 values,
// so this mock delegates to the Web Crypto generator Node provides. Jest
// picks up a root `__mocks__/<package>` automatically; application code
// never imports this file.

export function randomUUID(): string {
  return globalThis.crypto.randomUUID();
}
